def count_queens(N):
    board = [-1] * N
    placed = 0                       # 퀸을 놓아 본 횟수
    answers = 0

    def safe(row, col):
        for r in range(row):
            if board[r] == col or abs(board[r] - col) == abs(r - row):
                return False
        return True

    def solve(row):
        nonlocal placed, answers
        if row == N:
            answers += 1
            return
        for col in range(N):
            if safe(row, col):
                placed += 1
                board[row] = col
                solve(row + 1)
                board[row] = -1

    solve(0)
    return answers, placed

for N in (4, 5, 6):
    a, p = count_queens(N)
    print(f'N={N}: 해 {a}개, 퀸을 놓아 본 횟수 {p}번 (아무 칸에나 놓는 전체 탐색: {N ** N}가지)')
